 FfxResource vectors{},sceneChange{},dilatedDepth{},dilatedMotion{},reconstructed{},canonicalDepth{},canonicalMotion{},scratch{};
 bool flowCreated=false,framesCreated=false;std::atomic<bool>busy{false},failed{false};uint64_t sequence=0;unsigned history=0;
