  renderW=scene.maxRenderWidth?scene.maxRenderWidth:scene.renderWidth;renderH=scene.maxRenderHeight?scene.maxRenderHeight:scene.renderHeight;width=color.width;height=color.height;format=color.pixelFormat;transfer=inputTransfer;flags=scene.flags&(RS_TEMPORAL_DEPTH_REVERSED|RS_TEMPORAL_DEPTH_INFINITE|RS_TEMPORAL_JITTERED_MOTION);
