  NSError*issue=nil;auto library=[optical.device newLibraryWithSource:source options:nil error:&issue];if(!library)throw std::runtime_error(issue.localizedDescription.UTF8String?:"Scene guide shaders could not compile");copyDepth=[optical.device newComputePipelineStateWithFunction:[library newFunctionWithName:@"depthImage"] error:&issue];copyFloatDepth=[optical.device newComputePipelineStateWithFunction:[library newFunctionWithName:@"floatDepth"] error:&issue];copyMotion=[optical.device newComputePipelineStateWithFunction:[library newFunctionWithName:@"motion"] error:&issue];if(!copyDepth||!copyFloatDepth||!copyMotion)throw std::runtime_error("Scene guide pipelines could not initialize");
