 }
};
struct Handle {RSGenerationOptions options;std::string directory;std::shared_ptr<State>state;std::mutex mutex;explicit Handle(const RSGenerationOptions&value):options(value),directory(value.shaderDirectory){options.shaderDirectory=directory.c_str();}};
struct Lease {std::shared_ptr<State>state;std::array<id<MTLTexture>,4>images;bool completed=false;~Lease(){if(!completed){state->failed=true;state->busy=false;}}};
int result(RSGenerationResult*out,unsigned code,const std::string&reason,bool encoded=false,bool ready=false,unsigned history=0,uint64_t sequence=0){if(out){out->status=code;out->encoded=encoded;out->ready=ready;out->generated=ready?1:0;out->historyFrames=history;out->sequence=sequence;std::snprintf(out->reason,sizeof(out->reason),"%s",reason.c_str());}return int(code);}
void*create(const RSGenerationOptions*options,RSGenerationResult*out){if(!options||options->size<sizeof(*options)||options->version!=1||!options->device||!options->shaderDirectory||!*options->shaderDirectory||!options->reserve||!options->release){result(out,RS_GENERATION_INVALID,"A device, declared shader directory and resource allocator are required");return nullptr;}try{return new Handle(*options);}catch(const std::exception&issue){result(out,RS_GENERATION_FAILED,issue.what());return nullptr;}}
