void destroy(void*opaque){delete static_cast<Handle*>(opaque);}
int encode(void*opaque,const RSGenerationSubmission*input,RSGenerationResult*out){return process(opaque,input,out,false);}
int prepare(void*opaque,const RSGenerationSubmission*input,RSGenerationResult*out){return process(opaque,input,out,true);}
}
extern "C" __attribute__((visibility("default")))const RSGenerationProvider*rsGetGenerationProvider(uint32_t version){static const RSGenerationProvider api{sizeof(api),1,create,encode,destroy,prepare};return version==1?&api:nullptr;}
